import json, urllib.request, urllib.error, time, uuid

BASE = "https://api.ivxholding.com"

def call(method, path, body=None, timeout=25):
    req = urllib.request.Request(f"{BASE}{path}",
        data=json.dumps(body).encode() if body is not None else None,
        headers={"Content-Type": "application/json", "Accept": "application/json"}, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, json.loads(r.read() or b"{}")
    except urllib.error.HTTPError as e:
        try: return e.code, json.loads(e.read() or b"{}")
        except Exception: return e.code, {}
    except Exception as ex:
        return 0, {"error": str(ex)}

# 1. Landing page reachable
try:
    with urllib.request.urlopen("https://www.ivxholding.com", timeout=25) as r:
        html = r.read().decode(errors="ignore")
    print(f"1. LANDING PAGE: HTTP {r.status}, {len(html)} bytes, has signup form: {'register' in html.lower() or 'sign' in html.lower()}")
except Exception as e:
    print(f"1. LANDING PAGE: FAIL {e}")

# 2. Registration (live, real account)
email = f"qa-final-{uuid.uuid4().hex[:8]}@ivx-qa-test.com"
pw = "QaFinal!2026#Test"
code, reg = call("POST", "/api/auth/register", {"email": email, "password": pw, "fullName": "QA Final Check"})
print(f"2. REGISTRATION: HTTP {code} ok={reg.get('ok', reg.get('success'))} user={bool(reg.get('user') or reg.get('userId'))} err={str(reg.get('error',''))[:80]}")

# 3. Sign in with that account
code2, login = call("POST", "/api/auth/login", {"email": email, "password": pw})
tok = (login.get("token") or login.get("accessToken") or (login.get("session") or {}).get("access_token"))
print(f"3. SIGN IN: HTTP {code2} ok={login.get('ok', login.get('success'))} token={bool(tok)} err={str(login.get('error',''))[:80]}")

# 4. Payment/checkout
