    c, r = call("GET", p)
    if c != 404:
        print(f"4. PAYMENT {p}: HTTP {c} {json.dumps(r)[:160]}")
c, r = call("POST", "/api/payments/create-checkout", {"email": email, "plan": "member"})
print(f"4. CHECKOUT POST: HTTP {c} {json.dumps(r)[:200]}")

open("/tmp/qa-final-email.txt", "w").write(email)
PYEOF

